WITH valid_products AS (SELECT * FROM products WHERE product_name LIKE '%Laptop%'), Summary AS (SELECT DATE_TRUNC('MONTH', launch_date) AS launch_month, COUNT(CASE WHEN category = 'Fashion' THEN 1 END) AS fashion_count, MIN(launch_date) AS first_launch_date FROM valid_products GROUP BY DATE_TRUNC('MONTH', launch_date)) SELECT launch_month, fashion_count FROM Summary ORDER BY fashion_count DESC
